def moore(n, trans, part, blocks, deadline=None):
    """Round based refinement; returns (part, blocks, converged)."""
    monotonic = time.monotonic
    for _ in range(MOORE_ROUNDS):
        if deadline is not None and monotonic() > deadline:
            return part, blocks, False
        getter = part.__getitem__
        marks = {}
        newpart = [0] * n
        count = 0
        for q in range(n):
            sig = (part[q],) + tuple(map(getter, trans[q]))
            ident = marks.get(sig)
            if ident is None:
                ident = count
                count += 1
                marks[sig] = ident
            newpart[q] = ident
        if count == blocks or count == n:
            return newpart, count, True
        part = newpart
        blocks = count
    return part, blocks, False


